function estimate=estimateV4TrackAFormalStorage(roundNumber)
root=v4SetupPaths();[~,meta]=v4Stage3SCandidateTable(root,roundNumber);base=fullfile(root,'results','stage3s','Stage55-A-point-anchored-provisional-lock-v2',meta.parameterVersion,'smoke');loaded=load(fullfile(base,'stage3s_smoke.mat'),'summary');records=loaded.summary.records;n=numel(records);
compact=struct('symbolErrors',zeros(n,4,'uint8'),'cfoSseBins',zeros(n,4),'runtimeSec',zeros(n,4,'single'),'detectedLabels',zeros(n,4,23,'uint16'),'estimatedCfoBins',zeros(n,4,23,'single'),'stageAccepted',false(n,23),'stageUsedLabel',zeros(n,23,'uint16'),'stageReleaseSec',nan(n,23,'single'),'stageEffectiveSec',nan(n,23,'single'),'stageFinalState',zeros(n,1,'uint8'));
for i=1:n
    x=records{i};for method=1:4,compact.symbolErrors(i,method)=x.metrics{method}.symbolErrors;compact.cfoSseBins(i,method)=x.metrics{method}.cfoSquaredErrorBins;compact.runtimeSec(i,method)=x.runtimeSec(method);compact.detectedLabels(i,method,:)=uint16(x.receivers{method}.detectedPhysicalBins);compact.estimatedCfoBins(i,method,:)=single(x.receivers{method}.estimatedCfoBins);end
    s=x.receivers{4};compact.stageAccepted(i,:)=s.virtualPilotAccepted;labels=s.vpUsedLabel;labels(~isfinite(labels))=0;compact.stageUsedLabel(i,:)=uint16(labels);compact.stageReleaseSec(i,:)=single(s.releaseAtSec);compact.stageEffectiveSec(i,:)=single(s.firstEffectiveTimeSec);compact.stageFinalState(i)=uint8(find(strcmp(s.finalLockState,{'POINT_ANCHORED_PENDING','PROVISIONAL','LOCKED','LOST'}),1));
end
folder=fullfile(root,'results','stage3s','reports');pilot=fullfile(folder,'track_a_formal_compact_storage_pilot.mat');save(pilot,'compact','-v7.3');info=dir(pilot);free=java.io.File(root).getFreeSpace();projected=1.25*info.bytes/n*400000;estimate=struct('pilotPackets',n,'pilotBytes',info.bytes,'bytesPerPacket',info.bytes/n,'formalPackets',400000,'conservativeStorageGiB',projected/2^30,'requiredFreeGiBAt1p5x',1.5*projected/2^30,'availableFreeGiB',double(free)/2^30,'storageGatePassed',double(free)>=1.5*projected,'recordSchema','numeric compact matrices; no IQ or MATLAB receiver objects');write(fullfile(folder,'RUN_COST_ESTIMATE_A_R5_COMPACT.json'),jsonencode(estimate,'PrettyPrint',true));write(fullfile(folder,'RUN_COST_ESTIMATE_A_R5_COMPACT.md'),sprintf('# Track A R5 compact formal storage estimate\n\n- Bytes/packet: %.1f\n- Conservative storage: %.3f GiB\n- Required free at 1.5x: %.3f GiB\n- Available: %.3f GiB\n- Gate: `%s`\n',estimate.bytesPerPacket,estimate.conservativeStorageGiB,estimate.requiredFreeGiBAt1p5x,estimate.availableFreeGiB,ternary(estimate.storageGatePassed,'PASS','FAIL')));
end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear c,end
